	}

	@Subscribe
	public void onGroundObjectSpawned(GroundObjectSpawned event)
	{
		addObject(event.getGroundObject());
	}

	@Subscribe
	public void onGroundObjectDespawned(GroundObjectDespawned event)
	{
		objects.remove(event.getGroundObject());
	}

	/**
	 * Reads the saved groups. Returns new objects on every call, so callers can edit them freely.
	 */
	List<HighlightGroup> readSavedGroups()
	{
		String json = config.groups();
		if (Strings.isNullOrEmpty(json))
		{
			return new ArrayList<>();
		}

		try
		{
			List<HighlightGroup> saved = gson.fromJson(json, GROUP_LIST_TYPE);
			if (saved != null)
			{
				saved.removeIf(group -> group == null);
				return saved;
			}
		}
		catch (JsonParseException e)
		{
			log.warn("Unable to parse saved highlight groups", e);
		}
		return new ArrayList<>();
	}

	void saveGroups(List<HighlightGroup> groups)
	{
		configManager.setConfiguration(CustomEntityHighlightConfig.GROUP, CustomEntityHighlightConfig.GROUPS_KEY,
			gson.toJson(groups, GROUP_LIST_TYPE));
	}

	/**
	 * Returns the indexes of the groups that match the NPC's current form, or null if none do.
	 */
	BitSet getMatchingGroups(NPCComposition current)
	{
		return nullIfEmpty(npcMatches(current.getId()));
	}

	/**
	 * Returns the indexes of the groups that match the object's current form, or null if none do.
	 */
	BitSet getMatchingGroups(ObjectComposition current)
	{
		return nullIfEmpty(objectMatches(current.getId()));
	}

	/**
	 * Returns the option or name, as the game writes it, that the group matched the NPC's current form on, or null if it doesn't match.
	 */
	String getMatchedText(int group, NPCComposition current)
	{
		return npcMatchedTexts.computeIfAbsent(matchKey(group, current.getId()),
			k -> matchers.get(group).matchedText(current.getName(), current.getActions()));
	}

	/**
	 * Returns the option or name, as the game writes it, that the group matched the object's current form on, or null if it doesn't match.
	 */
	String getMatchedText(int group, ObjectComposition current)
	{
		return objectMatchedTexts.computeIfAbsent(matchKey(group, current.getId()),
			k -> matchers.get(group).matchedText(current.getName(), current.getActions()));
	}

	private static long matchKey(int group, int id)
	{
		return ((long) group << 32) | (id & 0xFFFFFFFFL);
	}

	private static BitSet nullIfEmpty(BitSet matches)
	{
		return matches.isEmpty() ? null : matches;
	}

	/**
	 * Returns the object's current form, following any varbit-driven transformation.
	 */
	ObjectComposition getCurrentComposition(TileObject object)
	{
		return getCurrentComposition(object.getId());
	}

	private ObjectComposition getCurrentComposition(int id)
	{
		ObjectComposition comp = client.getObjectDefinition(id);
		if (comp != null && comp.getImpostorIds() != null)
		{
			comp = comp.getImpostor();
		}
		return comp;
	}

	private void loadGroups()
	{
		List<HighlightGroup> loaded = readSavedGroups();
		List<GroupMatcher> loadedMatchers = new ArrayList<>(loaded.size());
		for (HighlightGroup group : loaded)
		{
			loadedMatchers.add(GroupMatcher.of(group));
		}

		groups = loaded;

		// Appearance changes don't affect which entities match, so only rescan when the entries change
		if (!loadedMatchers.equals(matchers))
		{
			matchers = loadedMatchers;
			npcMatches.clear();
			objectMatches.clear();
			npcMatchedTexts.clear();
			objectMatchedTexts.clear();
			npcs.clear();
			objects.clear();

			if (client.getGameState() == GameState.LOGGED_IN)
			{
				rescan(client.getTopLevelWorldView());
			}
		}
	}

	private void rescan(WorldView worldView)
	{
		for (NPC npc : worldView.npcs())
		{
			addNpc(npc);
		}

		Scene scene = worldView.getScene();
		for (Tile[][] plane : scene.getTiles())
		{
			for (Tile[] row : plane)
			{
				for (Tile tile : row)
				{
					if (tile == null)
					{
						continue;
					}

					GameObject[] gameObjects = tile.getGameObjects();
					if (gameObjects != null)
					{
						for (GameObject gameObject : gameObjects)
						{
							// Players and NPCs also occupy game object slots
							if (gameObject != null && !(gameObject.getRenderable() instanceof Actor))
							{
								addObject(gameObject);
							}
						}
					}

					addObject(tile.getWallObject());
					addObject(tile.getDecorativeObject());
					addObject(tile.getGroundObject());
				}
			}
		}

		for (WorldView subWorldView : worldView.worldViews())
		{
			rescan(subWorldView);
		}
	}

	private void addNpc(NPC npc)
	{
		if (matchers.isEmpty() || npc == null)
		{
			return;
		}

		NPCComposition comp = npc.getComposition();
		if (comp == null)
		{
			return;
		}

		if (!npcMatches(comp.getId()).isEmpty() || anyIdMatches(comp.getConfigs(), this::npcMatches))
		{
			npcs.add(npc);
		}
	}

	private void addObject(TileObject object)
	{
		if (matchers.isEmpty() || object == null)
		{
			return;
		}

		ObjectComposition comp = client.getObjectDefinition(object.getId());
		if (comp == null)
		{
			return;
		}

		if (!objectMatches(comp.getId()).isEmpty() || anyIdMatches(comp.getImpostorIds(), this::objectMatches))
		{
			objects.add(object);
		}
	}

	private BitSet npcMatches(int id)
	{
		return npcMatches.computeIfAbsent(id, i ->
		{
			NPCComposition comp = client.getNpcDefinition(i);
			return comp != null ? matchingGroups(comp.getName(), comp.getActions(), comp.isInteractible()) : new BitSet();
		});
	}

	private BitSet objectMatches(int id)
	{
		return objectMatches.computeIfAbsent(id, i ->
		{
			ObjectComposition comp = client.getObjectDefinition(i);
			// Objects have no clickable flag; whether they have options decides it
			return comp != null ? matchingGroups(comp.getName(), comp.getActions(), true) : new BitSet();
		});
	}

	private static boolean anyIdMatches(int[] ids, IntFunction<BitSet> matches)
	{
		if (ids == null)
		{
			return false;
		}

		for (int id : ids)
		{
			if (id != -1 && !matches.apply(id).isEmpty())
			{
				return true;
			}
		}
		return false;
	}

	private BitSet matchingGroups(String name, String[] actions, boolean clickable)
	{
		BitSet matches = new BitSet();
		for (int i = 0; i < matchers.size(); i++)
		{
			if (matchers.get(i).matches(name, actions, clickable))
			{
				matches.set(i);
			}
		}
		return matches;
	}
}

package com.customentityhighlight;

import com.google.common.base.Strings;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import lombok.EqualsAndHashCode;
import lombok.ToString;
import lombok.Value;
import net.runelite.client.util.Text;

/**
 * The parsed entries of a {@link HighlightGroup}. Equal matchers match exactly the same entities.
 */
@Value
class GroupMatcher
{
	// Unnamed definitions are named "null" in the cache
	private static final String NULL_NAME = "null";

	// Either a regex in slashes, which may contain commas, or anything up to the next comma or newline
	private static final Pattern ENTRY = Pattern.compile("\\s*(-?\\s*/.*?/)\\s*(?:[,\\n]|$)|([^,\\n]*)[,\\n]?");

	// Prefix for entries that stop an entity from matching
	private static final String EXCLUDE_PREFIX = "-";

	List<String> options;
	List<String> names;
	// Whether to skip entities that can't be interacted with
	boolean interactableOnly;

	// Patterns in entry order, compiled from the entries above so equal entries always give equal patterns
	@EqualsAndHashCode.Exclude
	@ToString.Exclude
	List<Pattern> optionPatterns;
	@EqualsAndHashCode.Exclude
	@ToString.Exclude
	List<Pattern> namePatterns;
	@EqualsAndHashCode.Exclude
	@ToString.Exclude
	List<Pattern> excludedOptionPatterns;
	@EqualsAndHashCode.Exclude
	@ToString.Exclude
	List<Pattern> excludedNamePatterns;

	static GroupMatcher of(HighlightGroup group)
	{
		List<String> options = splitEntries(group.getMenuOptions());
		List<String> names = splitEntries(group.getEntityNames());
		return new GroupMatcher(options, names, group.isInteractableOnly(), compileAll(options, false),
			compileAll(names, false), compileAll(options, true), compileAll(names, true));
	}

	/**
	 * Splits a list of option or name entries separated by commas or newlines. Commas inside a regex entry don't split it.
	 */
	static List<String> splitEntries(String text)
	{
		List<String> entries = new ArrayList<>();
		Matcher matcher = ENTRY.matcher(Strings.nullToEmpty(text));
		while (matcher.find())
		{
			String entry = matcher.group(1) != null ? matcher.group(1) : matcher.group(2).trim();
			if (!entry.isEmpty())
			{
				entries.add(entry);
			}
		}
		return entries;
	}

	/**
	 * Returns a message for each regex entry in the text that doesn't compile.
	 */
	static List<String> invalidEntries(String text)
	{
		List<String> errors = new ArrayList<>();
		for (String entry : splitEntries(text))
		{
			try
			{
				compile(entry);
			}
			catch (PatternSyntaxException e)
			{
				errors.add(entry + ": " + e.getDescription());
			}
		}
		return errors;
	}

	/**
	 * Compiles the entries that are, or aren't, exclusions.
	 */
	private static List<Pattern> compileAll(List<String> entries, boolean excluded)
	{
		List<Pattern> patterns = new ArrayList<>();
		for (String entry : entries)
		{
			if (isExclusion(entry) != excluded)
			{
				continue;
			}

			try
			{
				patterns.add(compile(entry));
			}
			catch (PatternSyntaxException e)
			{
				// Ignore invalid regexes; the panel points them out
			}
		}
		return patterns;
	}

	/**
	 * Whether the entry starts with a hyphen, so entities it matches are never highlighted. A lone hyphen is literal.
	 */
	private static boolean isExclusion(String entry)
	{
		return entry.length() > 1 && entry.startsWith(EXCLUDE_PREFIX);
	}

	private static boolean isRegex(String entry)
	{
		return entry.length() > 2 && entry.startsWith("/") && entry.endsWith("/");
	}

	/**
	 * Compiles an entry, without any exclusion prefix, into a case-insensitive pattern that must match the whole text.
	 * Entries in slashes are regexes; otherwise * matches any text and everything else is literal.
	 */
	private static Pattern compile(String entry)
	{
		if (isExclusion(entry))
		{
			entry = entry.substring(EXCLUDE_PREFIX.length()).trim();
		}

		if (isRegex(entry))
		{
			return Pattern.compile(entry.substring(1, entry.length() - 1), Pattern.CASE_INSENSITIVE);
		}

		StringBuilder regex = new StringBuilder();
		String[] parts = entry.split("\\*", -1);
		for (int i = 0; i < parts.length; i++)
		{
			if (i > 0)
			{
				regex.append(".*");
			}
			if (!parts[i].isEmpty())
			{
				regex.append(Pattern.quote(parts[i]));
			}
		}
		return Pattern.compile(regex.toString(), Pattern.CASE_INSENSITIVE);
	}

	boolean isEmpty()
	{
		return options.isEmpty() && names.isEmpty();
	}

	/**
	 * Whether a definition with this name and menu actions matches any of the entries and none of the exclusions,
	 * ignoring interactability.
	 */
	boolean matches(String name, String[] actions)
	{
		return matchedText(name, actions) != null;
	}

	/**
	 * Whether a definition matches any of the entries and, if the group is limited to interactable entities, is one.
	 * An entity is interactable if the game lets it be clicked and it has an option other than Examine, which
	 * definitions don't list.
	 */
	boolean matches(String name, String[] actions, boolean clickable)
	{
		if (interactableOnly && !(clickable && hasAction(actions)))
		{
			return false;
		}
		return matches(name, actions);
	}

	private static boolean hasAction(String[] actions)
	{
		if (actions != null)
		{
			for (String action : actions)
			{
				if (action != null && !Text.removeTags(action).trim().isEmpty())
				{
					return true;
				}
			}
		}
		return false;
	}

	/**
	 * Returns the action matched by the first option entry that matches one of them, or else the name if a name
	 * entry matches it, as the game writes it without tags. Null if nothing matches or any exclusion entry matches.
	 */
	String matchedText(String name, String[] actions)
	{
		List<String> actionTexts = actionTexts(actions);
		List<String> nameTexts = nameTexts(name);
		if (firstMatch(excludedOptionPatterns, actionTexts) != null || firstMatch(excludedNamePatterns, nameTexts) != null)
		{
			return null;
		}

		String action = firstMatch(optionPatterns, actionTexts);
		return action != null ? action : firstMatch(namePatterns, nameTexts);
	}

	/**
	 * Returns the index of the option matched by the first option entry that matches any of them, or -1 if none
	 * match. Null options are skipped, and when one entry matches several options the earliest wins.
	 */
	int firstMatchingOption(String[] options)
	{
		for (Pattern pattern : optionPatterns)
		{
			for (int i = 0; i < options.length; i++)
			{
				if (options[i] != null && pattern.matcher(Text.removeTags(options[i])).matches())
				{
					return i;
				}
			}
		}
		return -1;
	}

	private static List<String> actionTexts(String[] actions)
	{
		if (actions == null)
		{
			return Collections.emptyList();
		}

		List<String> texts = new ArrayList<>(actions.length);
		for (String action : actions)
		{
			if (action != null)
			{
				texts.add(Text.removeTags(action));
			}
		}
		return texts;
	}

	private static List<String> nameTexts(String name)
	{
		if (name == null)
		{
			return Collections.emptyList();
		}

		String text = Text.removeTags(name);
		return NULL_NAME.equals(text) ? Collections.emptyList() : Collections.singletonList(text);
	}

	/**
	 * Returns the text matched by the first pattern that matches any of them, or null if none match.
	 */
	private static String firstMatch(List<Pattern> patterns, List<String> texts)
	{
		for (Pattern pattern : patterns)
		{
			for (String text : texts)
			{
				if (pattern.matcher(text).matches())
				{
					return text;
				}
			}
		}
		return null;
	}
}

package com.customentityhighlight;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.awt.Color;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import lombok.Data;

/**
 * Which NPCs and objects to highlight (by menu option or name) and how to highlight them.
 * Saved to config as JSON, so colors are stored as ARGB ints.
 */
@Data
class HighlightGroup
{
	static final int MIN_BORDER_WIDTH = 1;
	static final int MAX_BORDER_WIDTH = 10;
	static final int MAX_OUTLINE_FEATHER = 4;

	private String name = "New group";
	private boolean enabled = true;
	// Whether the panel hides this group's settings
	private boolean collapsed = false;
	// Whether the panel shows this group's advanced settings
	private boolean advancedExpanded = false;
	// Comma-separated lists; an entity matches if any entry in any list matches
	private String menuOptions = "";
	private String entityNames = "";
	private boolean highlightNpcs = true;
	private boolean highlightObjects = true;
	// Skips NPCs and objects that can't be clicked or have no options besides Examine
	private boolean interactableOnly = false;
	// Moves the option matched by the first matching menuOptions entry to left-click
	private boolean swapLeftClick = false;
	private HighlightStyle style = HighlightStyle.OUTLINE;
	private int highlightColor = Color.CYAN.getRGB();
	private int fillColor = new Color(0, 255, 255, 20).getRGB();
	private int borderWidth = 2;
	private int outlineFeather = 0;
	private boolean showNames = false;
	private LabelSource labelSource = LabelSource.NAME;
	// Text shown when labelSource is CUSTOM; blank uses the entity's name
	private String customLabel = "";

	Color getHighlightColorValue()
	{
		return new Color(highlightColor, true);
	}

	Color getFillColorValue()
	{
		return new Color(fillColor, true);
	}

	HighlightStyle getStyleOrDefault()
	{
		// Null if the saved style no longer exists
		return style != null ? style : HighlightStyle.OUTLINE;
	}

	/**
	 * Encodes the group as Base64 JSON, for sharing as text.
	 */
	String toExportString(Gson gson)
	{
		return Base64.getEncoder().encodeToString(gson.toJson(this).getBytes(StandardCharsets.UTF_8));
	}

	/**
	 * Decodes a group from {@link #toExportString}. Whitespace is ignored. Returns null if the text isn't a group.
	 */
	static HighlightGroup fromExportString(Gson gson, String text)
	{
		if (text == null)
		{
			return null;
		}

		try
		{
			byte[] json = Base64.getDecoder().decode(text.replaceAll("\\s", ""));
			return gson.fromJson(new String(json, StandardCharsets.UTF_8), HighlightGroup.class);
		}
		catch (IllegalArgumentException | JsonParseException e)
		{
			// Not Base64, or not a group's JSON
			return null;
		}
	}

	LabelSource getLabelSourceOrDefault()
	{
		// Null if the saved label source no longer exists
		return labelSource != null ? labelSource : LabelSource.NAME;
	}
}

