package com.customentityhighlight;

import java.util.Arrays;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GroupMatcherTest
{
	private static final String[] BANKER_ACTIONS = {"Talk-to", "Bank", "Collect", null, null};

	private static GroupMatcher matcher(String options, String names)
	{
		HighlightGroup group = new HighlightGroup();
		group.setMenuOptions(options);
		group.setEntityNames(names);
		return GroupMatcher.of(group);
	}

	@Test
	public void matchesMenuOptions()
	{
		assertTrue(matcher("bank", "").matches("Banker", BANKER_ACTIONS));
		assertTrue(matcher("coll*", "").matches("Banker", BANKER_ACTIONS));
		assertFalse(matcher("ban", "").matches("Banker", BANKER_ACTIONS));
	}

	@Test
	public void matchesNames()
	{
		assertTrue(matcher("", "banker").matches("Banker", null));
		assertTrue(matcher("", "*chest").matches("<col=ffff>Bank chest</col>", null));
		assertFalse(matcher("", "bank").matches("Banker", null));
	}

	@Test
	public void wildcardNameIgnoresUnnamedDefinitions()
	{
		assertFalse(matcher("", "*").matches("null", null));
	}

	@Test
	public void wildcardsTreatRegexCharactersLiterally()
	{
		assertTrue(matcher("", "rune (p++)*").matches("Rune (p++) dagger", null));
		assertFalse(matcher("", "bank.").matches("Banks", null));
	}

	@Test
	public void matchesRegexes()
	{
		assertTrue(matcher("/coll(ect)?/", "").matches("Banker", BANKER_ACTIONS));
		assertTrue(matcher("", "/(iron|steel) rocks/").matches("<col=ffff>Steel rocks</col>", null));
		assertFalse(matcher("", "/(iron|steel) rocks/").matches("Coal rocks", null));
		// Regexes must match the whole text, like wildcards
		assertFalse(matcher("", "/bank/").matches("Banker", null));
	}

	@Test
	public void regexesCanContainCommas()
	{
		assertEquals(Arrays.asList("/a{2,3}/", "bank", "/x,y/"), GroupMatcher.splitEntries(" /a{2,3}/ , bank,, /x,y/"));
		assertTrue(matcher("", "/ba{1,2}nker/, chest").matches("Banker", null));
	}

	@Test
	public void newlinesSeparateEntries()
	{
		assertEquals(Arrays.asList("bank", "/x,y/", "chest", "banker"),
			GroupMatcher.splitEntries("bank\n/x,y/\r\n\nchest, banker\n"));
	}

	@Test
	public void reportsFirstMatchedText()
	{
		// Entries are checked in the order written, options before names, and the entity's own text is returned
		assertEquals("Collect", matcher("talk, coll*, bank", "banker").matchedText("Banker", BANKER_ACTIONS));
		assertEquals("Banker", matcher("pickpocket", "chest, /bank.*/").matchedText("Banker", BANKER_ACTIONS));
		assertEquals("Bank", matcher("bank", "").matchedText("Banker", new String[]{"<col=ff0000>Bank</col>"}));
		assertEquals("Banker", matcher("", "banker").matchedText("<col=ffff00>Banker</col>", null));
		assertNull(matcher("steal", "chest").matchedText("Banker", BANKER_ACTIONS));
	}

	@Test
	public void findsFirstMatchingOption()
	{
		// Entries are tried in the order written; for each, the earliest matching option wins
		String[] options = {"Talk-to", null, "Bank", "Bank-all", "Collect"};
		assertEquals(4, matcher("coll*, bank*", "").firstMatchingOption(options));
		assertEquals(2, matcher("pickpocket, bank*", "").firstMatchingOption(options));
		assertEquals(-1, matcher("steal", "banker").firstMatchingOption(options));
	}

	@Test
	public void interactableOnlySkipsEntitiesWithoutOptions()
	{
		HighlightGroup group = new HighlightGroup();
		group.setEntityNames("bank booth");
		GroupMatcher any = GroupMatcher.of(group);
		group.setInteractableOnly(true);
		GroupMatcher interactable = GroupMatcher.of(group);

		String[] none = {null, "", "<col=ff0000></col>", null, null};
		assertTrue(any.matches("Bank booth", none, true));
		assertFalse(interactable.matches("Bank booth", none, true));
		assertFalse(interactable.matches("Bank booth", null, true));
		assertTrue(interactable.matches("Bank booth", new String[]{null, "Bank", null}, true));
		// NPCs the game won't let you click don't count, even with options
		assertFalse(interactable.matches("Bank booth", BANKER_ACTIONS, false));
		// Changing the setting changes which entities match, so the plugin rescans
		assertFalse(any.equals(interactable));
	}

	@Test
	public void ignoresInvalidRegexes()
	{
		GroupMatcher matcher = matcher("", "/bank(/, banker");
		assertTrue(matcher.matches("Banker", null));
		assertFalse(matcher.matches("Bank(", null));
		assertEquals(1, GroupMatcher.invalidEntries("/bank(/, banker").size());
		assertTrue(GroupMatcher.invalidEntries("/bank/, bank(").isEmpty());
	}

	@Test
	public void exclusionsPreventMatches()
	{
		// An exclusion in either list stops a match from the other
		assertFalse(matcher("bank", "-banker").matches("Banker", BANKER_ACTIONS));
		assertTrue(matcher("bank", "-banker").matches("Bank chest", new String[]{"Bank"}));
		assertFalse(matcher("-talk*", "bank*").matches("Banker", BANKER_ACTIONS));
		assertTrue(matcher("-talk*", "bank*").matches("Bank chest", new String[]{"Bank"}));
		assertNull(matcher("bank, collect", "- /bank.*/").matchedText("Banker", BANKER_ACTIONS));
		// Exclusions alone match nothing
		assertFalse(matcher("-steal", "-chest").matches("Banker", BANKER_ACTIONS));
		// A lone hyphen is literal
		assertTrue(matcher("", "-").matches("-", null));
	}

	@Test
	public void excludedRegexesCanContainCommas()
	{
		assertEquals(Arrays.asList("-/a{2,3}/", "- /x,y/", "bank"), GroupMatcher.splitEntries("-/a{2,3}/, - /x,y/, bank"));
		assertFalse(matcher("bank", "-/ba{1,2}nker/").matches("Banker", BANKER_ACTIONS));
		assertEquals(1, GroupMatcher.invalidEntries("-/bank(/, -banker").size());
	}

	@Test
	public void matchesIfAnyListMatches()
	{
		GroupMatcher matcher = matcher("collect", "banker");
		assertTrue(matcher.matches("Banker", null));
		assertTrue(matcher.matches("Rock", BANKER_ACTIONS));
		assertFalse(matcher.matches("Rock", new String[]{"Mine"}));
	}

	@Test
	public void sameEntriesGiveEqualMatchers()
	{
		assertTrue(matcher("bank, collect", "banker").equals(matcher(" bank ,collect", "banker")));
	}
}

package com.customentityhighlight;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.awt.Color;
import java.nio.charset.StandardCharsets;
import java.util.Base64;
import java.lang.reflect.Type;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class HighlightGroupTest
{
	private static final Type GROUP_LIST_TYPE = new TypeToken<List<HighlightGroup>>()
	{
	}.getType();

	private final Gson gson = new Gson();

	@Test
	public void roundTripsThroughJson()
	{
		HighlightGroup group = new HighlightGroup();
		group.setName("Thieving");
		group.setCollapsed(true);
		group.setSwapLeftClick(true);
		group.setInteractableOnly(true);
		group.setAdvancedExpanded(true);
		group.setMenuOptions("pick*, steal-from");
		group.setStyle(HighlightStyle.CLICKBOX);
		group.setHighlightColor(new Color(255, 128, 0, 200).getRGB());
		group.setShowNames(true);
		group.setLabelSource(LabelSource.MATCH);
		group.setCustomLabel("Pickpocket");

		List<HighlightGroup> loaded = gson.fromJson(gson.toJson(Collections.singletonList(group), GROUP_LIST_TYPE), GROUP_LIST_TYPE);

		assertEquals(Collections.singletonList(group), loaded);
		assertEquals(new Color(255, 128, 0, 200), loaded.get(0).getHighlightColorValue());
	}

	@Test
	public void roundTripsThroughExportString()
	{
		HighlightGroup group = new HighlightGroup();
		group.setName("Banks");
		group.setMenuOptions("bank\ncollect");
		group.setEntityNames("/bank(er)?/");
		group.setStyle(HighlightStyle.TILE);

		String exported = group.toExportString(gson);
		// Line breaks added by chat apps or editors are ignored
		String wrapped = exported.substring(0, 10) + "\r\n " + exported.substring(10) + "\n";

		assertEquals(group, HighlightGroup.fromExportString(gson, exported));
		assertEquals(group, HighlightGroup.fromExportString(gson, wrapped));
	}

	@Test
	public void rejectsInvalidExportStrings()
	{
		assertNull(HighlightGroup.fromExportString(gson, null));
		assertNull(HighlightGroup.fromExportString(gson, ""));
		assertNull(HighlightGroup.fromExportString(gson, "not base64!"));
		assertNull(HighlightGroup.fromExportString(gson, base64("[1, 2]")));
		assertNull(HighlightGroup.fromExportString(gson, base64("hello")));
		assertNull(HighlightGroup.fromExportString(gson, base64("{\"name\": ")));
	}

	private static String base64(String text)
	{
		return Base64.getEncoder().encodeToString(text.getBytes(StandardCharsets.UTF_8));
	}

	@Test
	public void missingFieldsUseDefaults()
	{
		List<HighlightGroup> loaded = gson.fromJson("[{\"name\":\"Old\",\"menuOptions\":\"bank\"}]", GROUP_LIST_TYPE);
		HighlightGroup group = loaded.get(0);

		assertTrue(group.isEnabled());
		assertFalse(group.isCollapsed());
		assertFalse(group.isSwapLeftClick());
		assertFalse(group.isInteractableOnly());
		assertFalse(group.isAdvancedExpanded());
		assertTrue(group.isHighlightNpcs());
		assertEquals(HighlightStyle.OUTLINE, group.getStyleOrDefault());
		assertEquals(2, group.getBorderWidth());
		assertEquals(LabelSource.NAME, group.getLabelSourceOrDefault());
	}

	@Test
	public void unknownStyleFallsBackToOutline()
	{
		List<HighlightGroup> loaded = gson.fromJson("[{\"style\":\"NOT_A_STYLE\"}]", GROUP_LIST_TYPE);

		assertEquals(HighlightStyle.OUTLINE, loaded.get(0).getStyleOrDefault());
	}
}
